fn reverse(a: &[char]) -> Vec<char> {
    // Pre-allocate a Vec with the same length as the input slice
    let mut b = Vec::with_capacity(a.len());
    // Iterate over `a` in reverse and push each character into `b`
    for &ch in a.iter().rev() {
        b.push(ch);
    }
    b
}

